// generated by tools/make_patchnotes.py from docs/release-notes-*.md
window.POE_PATCH_NOTES = [{"title":"scarab hub, profit calculator, price boards and pick-and-check helpers","blocks":[{"p":[["t","Interactive tools inside the mechanic cheat sheets, with game icons and live prices from GGG's hourly currency exchange (no trade-site searches)."]]},{"ul":[{"li":[["b","Scarab hub"],["t"," (Scarabs, Atlas): every scarab with its icon, price, effect and limit per map. Build "],["b","My setup"],["t"," (scarabs, map, embers, astrolabes, orbs) and see its cost per map; pick an Atlas strategy to fill it in."]]},{"li":[["b","Profit calculator"],["t",": maps per hour, cost per map and expected drops give profit per map and per hour, next to the community's own rough estimates."]]},{"li":[["b","Price boards"],["t",": fossils by Delve biome (with the best biome now), essences by tier, lifeforce per 1,000, oils, Delirium orbs and Simulacrum, Breach and Legion fragments, Expedition currencies, catalysts (Ultimatum, Vendor) and beasts with recipe beasts marked."]]},{"li":[["b","Pick-and-check helpers"],["t",": Eldritch altars, Ultimatum modifiers, Sanctum afflictions and Expedition remnants. Tick what your build relies on, click what you see, and get a verdict that names anything run-ending for your build, with the reason and its sources."]]},{"li":[["b","Temple room planner"],["t"," (Incursion): pick a goal, set your rooms' tiers, see what still needs upgrading. Saved."]]},{"li":[["b","In game"],["t"," (Alt+C): the boards, checkers and the temple planner are on the sheet's new "],["b","Tools"],["t"," tab, click-only."]]},{"li":[["t","The ratings, room values and strategy setups come from community guides and player reports (as of 3.29), each checked against its source by three reviewers, and update from the app's server like the guides."]]}]}],"v":"v2.5.23","date":"2026-11-06"},{"title":"in-depth guides for every league mechanic, and a Syndicate planner","blocks":[{"ul":[{"li":[["b","Mechanic guides"],["t"," in Cheat sheets for 21 mechanics: Betrayal, Blight, Delve, Incursion, Expedition, Heist, Sanctum, Ultimatum, Ritual, Harvest, Breach, Legion, Abyss, Delirium, Bestiary, Eldritch altars, Essences, Kingsmarch, vendor recipes, Mercenaries and Atlas strategies."]],"ul":[{"li":[["t","Researched from written community guides and GGG's patch notes, every point checked against its source, as of 3.29 (each guide shows when it was checked)."]]},{"li":[["t","Filter by stage: league start, mid, late or SSF."]]},{"li":[["t","How to run it, strategies with atlas passives and scarabs, dangers, what to sell, rough profit estimates (who and when), changes by patch, and links to the written guides."]]},{"li":[["t","In game: a short quick card, with the reference tables one click away."]]},{"li":[["t","They update from the app's server, so the next league's changes arrive without a download."]]}]},{"li":[["b","Syndicate planner"],["t"," (Betrayal): mirror your board, pick a goal, and get the next moves (execute, interrogate, betray, release, which safehouse to run) with the reason for each."]]}]}],"v":"v2.5.22","date":"2026-11-05"},{"title":"edit your loot filter in game, like Scalpel","blocks":[{"p":[["t","Hover an item and press "],["b","Ctrl+Shift+D"],["t",". The price-check window becomes a filter editor for that item, next to your inventory or stash, as tall as the game. It edits your filter's own blocks, and every save reloads the filter in game (turn that off in Settings → Hotkeys)."]]},{"ul":[{"li":[["b","Switch Tier"],["t",": every tier of the same kind, each drawn the way the game draws it. Pick one and the item moves there. Tiers that can't take it aren't listed."]]},{"li":[["b","Hide"],["t",": says what it will do (hide the tier, or move the item to a hidden tier), then does it."]]},{"li":[["b","The item"],["t",": its art, price, item level and stack, plus "],["b","Use Zone Level"],["t"," on a map."]]},{"li":[["b","Thresholds"],["t",": stack size, quality and memory strands as a bar of ranges. Pick a range to edit the tier that shows it, or move a boundary."]]},{"li":[["b","Edit Tier"],["t",":"]],"ul":[{"li":[["t","the tier's items with prices"]]},{"li":[["t","Show / Hide"]]},{"li":[["t","the label with the font size and "],["b","Text / Border / Background"],["t"," colour pickers (your filter's most used colours, hex and RGBA)"]]},{"li":[["b","Effects"],["t",": minimap icon (size, colour, shape), light beam, drop sound with a preview"]]}]},{"li":[["b","Economy audit"],["t",": slide a price and move the tier's dearer items up a tier or the cheaper ones down. On unique tiers, by dust too."]]},{"li":[["b","Uniques on this base"],["t",": cards with prices."]]},{"li":[["b","History"],["t",": undo your last 30 edits, restore a saved version, make a checkpoint."]]},{"li":[["b","Online filters"],["t"," (FilterBlade, the PoE site): import one to edit a local copy. "],["b","Check for Filter Updates"],["t"," fetches the new version; "],["b","Update"],["t"," puts your edits on it and switches back. One game command per click."]]},{"li":[["t","Better filter matching for pasted and Ctrl+D items: magic and Superior bases, unusable items, map tier, Eldritch implicits, mirrored / fractured / synthesised / transfigured and more."]]},{"li":[["t","The game's label font and alert sounds download once, the first time you need them."]]}]}],"v":"v2.5.21","date":"2026-11-03"},{"title":"search text like poe.re","blocks":[{"p":[["b","Tools → Search text"],["t"," now does what poe.re does, with eleven tabs:"]]},{"ul":[{"li":[["t","The search box takes the game's full "],["b","250 characters"],["t"," (it was 50)."]]},{"li":[["b","Maps"],["t",": mods to avoid or want, plus at least this much quantity, pack size, rarity, more maps, more currency, more scarabs or more div cards."]],"ul":[{"li":[["t","Also quality types, rarity, corrupted, unidentified, map types (Shaper, Elder, Blighted…) and a price-note range."]]}]},{"li":[["b","Vendor"],["t",": 2–6 links, 6 sockets, linked colours in any order (e.g. the chromatic recipe), at least N sockets of a colour, levelling mods, item type and rarity."]]},{"li":[["b","Items"],["t",": pick a base (71 groups) and the mods it can roll. Rare: a minimum per mod, matched on the rolled value. Magic: the affix names, for alteration crafting."]]},{"li":[["b","Gems"],["t",": pick gems or "],["b","Add my build's gems"],["t",", with a minimum level and quality."]]},{"li":[["b","Scarabs"],["t",", "],["b","Tattoos"],["t"," (and runegrafts), "],["b","Beasts"],["t"," and "],["b","Gwennen"],["t"," come with this league's prices. "],["b","Pick the dearest in range"],["t"," fills the box with the most expensive first."]]},{"li":[["b","Heist"],["t",": contracts by job and level (with a Gianna preset) and by target."]]},{"li":[["b","Add my own text"],["t"," after the search, "],["b","Copy automatically"],["t",", and presets that keep every tab. Your old presets still load."]]}]}],"v":"v2.5.20","date":"2026-11-03"},{"title":"patch notes in the app","blocks":[{"ul":[{"li":[["b","Settings → Patch notes"],["t"," lists what every release brought, newest first. The newest is open; click any release to open or close it, and "],["b","Show older releases"],["t"," lists the rest."]],"ul":[{"li":[["t","The version you have is marked "],["b","installed"],["t",", and when a newer one is out it says so at the top."]]},{"li":[["t","Each release ships its own notes, so the list is always up to date after an update."]]}]},{"li":[["b","Find a setting"],["t"," skips the patch notes, so it still finds only settings."]]}]}],"v":"v2.5.19","date":"2026-11-01"},{"title":"your builds at launch, the app without a build, and an Atlas tree","blocks":[{"ul":[{"li":[["b","Builds page"],["t",": the app opens on your saved builds (newest opened first, with ascendancy, level and Atlas strategy) above the paste box. Importing a new build offers ☆ Save, saving asks for a name, and ⋯ renames, links an Atlas strategy or deletes. Up to 100 builds, with search."]]},{"li":[["b","No build needed"],["t",": the sidebar is there from launch. Watcher's Eye & co., Search text, Div cards, Cheat sheets, the Atlas tree, Dust explorer, Market and the Trade helper all work without importing a build. Gear, the planner and the skill tree tools appear once you load one."]]},{"li":[["b","Atlas tree"],["t"," (Tools → Atlas tree): import an official Atlas tree link, a PoB code or pobb.in link with Atlas links in its notes, or a list of node names. See your path on the tree with the in-game icons and background, search it, and save it as a strategy with notes. Link a strategy to each saved build; the build's card shows it, and the strategy shows which builds use it."]]},{"li":[["b","Skill tree"],["t",": the in-game background behind the tree, and masteries drawn like in game: grey when locked, lit when a notable next to them is taken, glowing with their pattern when chosen."]]}]}],"v":"v2.5.18","date":"2026-11-01"},{"title":"screen scaling in diagnostics","blocks":[{"ul":[{"li":[["b","Settings → Copy diagnostics"],["t"," now lists every screen with its size, position and scaling, and says "],["b","Mixed scaling: yes"],["t"," when your screens use different scaling (e.g. 100% and 150%). On such setups the in-game overlays can look stretched or sit slightly off on the second screen. If you see that, send the diagnostics so it can be fixed for your setup."]]}]}],"v":"v2.5.17","date":"2026-11-01"},{"title":"Settings in tabs, and a saved POESESSID that says it's saved","blocks":[{"ul":[{"li":[["b","Settings has tabs"],["t"," — Look, Alerts, Hotkeys, In game, Account, Updates, Help — and opens on the one you used last. "],["b","Find a setting"],["t"," at the top searches every tab at once (a setting's name, its help text or its choices)."]]},{"li":[["t","Hotkeys and chat macros are together on "],["b","Hotkeys"],["t","; the app-over-the-game, tray and learned-filter options are on "],["b","In game"],["t","."]]},{"li":[["b","POESESSID"],["t",": it was always kept on your PC between starts, but the box looked empty after a restart. Settings → Account now says "],["b","Saved on this PC"],["t",", has a "],["b","Remove"],["t"," button, tells you if a save fails, and explains when pathofexile.com has ended the session (it does when you log out there)."]]}]}],"v":"v2.5.16","date":"2026-11-01"},{"title":"loot filter tools","blocks":[{"p":[["b","⏚ Loot filter"],["t"," (Tools → Loot filter, works without a build) tunes your own .filter file:"]]},{"ul":[{"li":[["b","Price re-tier"],["t",": for NeverSink / FilterBlade filters. It finds items whose price today is far from their tier (currency, cards, scarabs and more from GGG's exchange feed; uniques from poe.ninja), with the tier they fit now. Tick the ones to change."]]},{"li":[["b","Build items"],["t",": highlights your build's rare bases (to craft on), its uniques' bases and its gems."]]},{"li":[["b","Your rules"],["t",": hide or show an item class or base types, with a look of your choice or the look of any tier in your filter."]]},{"li":[["b","Find an item"],["t",": paste an item to see which block of your filter shows or hides it, with "],["b","Hide it"],["t"," / "],["b","Highlight it"],["t","."]]},{"li":[["b","Checkpoints"],["t",": the app keeps a copy before every save; restore any of them."]]},{"li":[["t","The "],["b","Ctrl+D price check"],["t"," shows which filter block catches the item, with "],["b","Hide it"],["t"," / "],["b","Highlight it"],["t","."]]}]},{"p":[["t","How it changes your filter:"]]},{"ul":[{"li":[["t","Everything the app adds is in one section at the top of the file, so it wins without the filter's own blocks being rewritten, and comes back after you download a new version of your filter (open it, Save)."]]},{"li":[["t","The app never touches the game: after saving, pick the filter again in game (Options → UI)."]]}]}],"v":"v2.5.15","date":"2026-11-01"},{"title":"the whole div card on hover","blocks":[{"ul":[{"li":[["b","Tools → Div cards"],["t",": hover a card (its picture or its name) to see the whole card the way the game shows it: the name, the full picture with the stack size (e.g. 1 / 8), the reward in the game's colours (unique, currency, gem, corrupted, item level…) and the flavour text. Before, only a cropped picture showed."]]},{"li":[["t","The reward and flavour text come from the community Path of Exile Wiki and update through the app's server between releases, like the drop areas."]]}]}],"v":"v2.5.14","date":"2026-11-01"},{"title":"div card value per area","blocks":[{"ul":[{"li":[["b","Div cards → By area"],["t"," now ranks areas by "],["b","≈ per 1000 drops"],["t",": the card value you'd expect per 1,000 items dropped there, from community drop weights (the Prohibited Library's stacked deck data, via maps-of-exile, MIT)."]],"ul":[{"li":[["t","These are estimates, not GGG numbers. Monster density isn't counted, so use it to compare areas."]]},{"li":[["b","4 voidstones"],["t"," (on by default) counts maps at area level 83, so cards that need a high level are included."]]},{"li":[["t","Cards without a known weight are left out and flagged ("],["b","+N?"],["t",")."]]}]},{"li":[["t","Open an area to see each card's odds (≈ one per how many drops) and its share of the value."]]}]}],"v":"v2.5.13","date":"2026-11-01"},{"title":"anoint helper in the Blight cheat sheet","blocks":[{"ul":[{"li":[["b","Anoint helper"],["t"," (Cheat sheets → Blight): every amulet, ring and blighted-map anoint with the oils it takes, shown with their in-game icons, and "],["b","what it costs right now"],["t"," (oil prices from GGG's currency exchange)."]],"ul":[{"li":[["b","Search"],["t"," a notable by name or by what it does (\"spell critical\")."]]},{"li":[["b","Sort"],["t"," cheapest or priciest first."]]},{"li":[["b","Pick oils"],["t"," to see what they make; one oil lists every recipe that uses it. Click a row to pick its oils."]]},{"li":[["b","Your build's"],["t"," current anoint is listed first; notables already in your tree are marked."]]},{"li":[["t","Over the game it's click-only, so it never takes your keyboard."]]}]}]}],"v":"v2.5.12","date":"2026-11-01"},{"title":"your character compare comes back after a restart, and settings stay put","blocks":[{"ul":[{"li":[["b","Compare again when the app starts"],["t"," (⚖ Compare with character…, on by default): the app runs your last character compare once at launch, so the gear marks, the gem socket picture and the link tags are there after an update or a restart without pressing Compare gear. Same requests as the button, never repeated on its own. Untick it to compare by hand."]]},{"li":[["b","Fix: in-game settings no longer reset."],["t"," The app-over-game, trade-cards and cheat-sheet hotkeys, close to tray, \"a click in the game puts it away\", the see-through setting and your chat macros could go back to their defaults after a restart once you changed any other setting. They're kept now."]]}]}],"v":"v2.5.11","date":"2026-11-01"},{"title":"one copy at a time, cleaner updates","blocks":[{"ul":[{"li":[["b","Only one PoB Trade Finder runs at a time."],["t"," Starting it again brings the running app forward, even from the tray, instead of opening a second copy. Two copies fought over the update, the hotkeys, the tray icon and the overlays."]]},{"li":[["b","Updates close the app properly"],["t",", the same way tray → Quit does. No tray icon is left behind that made the app look like it was still running."]]},{"li":[["b","The update waits until the old copy has really exited"],["t"," before swapping the files (it used to wait a fixed 3 seconds, which could leave the update half done), and the new copy waits for the old one instead of seeing it as \"already running\"."]]}]},{"p":[["t","Note: this update itself still runs the old update steps. If an update ever seems stuck, tray icon → Quit on any extra copies and start the app again."]]}],"v":"v2.5.10","date":"2026-11-01"},{"title":"deeper cheat sheets, div card art, skill tree icons, saved characters","blocks":[{"ul":[{"li":[["b","Cheat sheets, much deeper"],["t",":"]],"ul":[{"li":[["b","Route"],["t"," for every act: each zone in order with its level, waypoint, quest steps and bosses. With Follow my act on, the zone you're in is highlighted."]]},{"li":[["b","Gems"],["t",": each quest's gem rewards and what you can buy after, for your build's class, with your build's gems highlighted."]]},{"li":[["b","24 mechanic sheets"],["t"," (9 new: Heist, Breach, Legion, Abyss, Delirium, Ritual, Labyrinth, scarabs, Atlas map tiers), and more detail in the others: every Blight anoint, Sanctum boons, pacts and relics, Expedition factions, Incursion rooms, Delve depths. Content the 3.29 reworks removed is left out. Long sheets get a filter box in the app."]]}]},{"li":[["b","Div cards"],["t",": card pictures (hover for a bigger one). The page shows your last prices straight away after a restart while it refreshes, and 51 cards whose names have an apostrophe now get their prices."]]},{"li":[["b","Skill tree"],["t",": the real passive icons on keystones, notables and small passives as you zoom in, in colour for your build and grey for the rest."]]},{"li":[["b","Compare with character"],["t",": ☆ Save a character (yours or a friend's) and compare it with one click next time."]]},{"li":[["b","Updates"],["t",": a clearer update banner (\"v2.5.9 is ready\", what's new, Later, Update now), and an "],["b","Update now"],["t"," button right in Settings after Check for updates."]]}]}],"v":"v2.5.9","date":"2026-11-01"},{"title":"a trade ledger — what you bought, profit, flips, people, reports","blocks":[{"ul":[{"li":[["b","Buying is tracked too."],["t"," Cards for whispers you send now end with "],["b","✓ Bought"],["t"," (at the "],["b","Paid"],["t"," price, with − / + and "],["i","in div"],["t","), "],["b","✗ Didn't happen"],["t",", "],["b","⌛ No answer"],["t"," or "],["b","Other"],["t",". When the game logs \"Trade accepted\" while you're buying, Bought is highlighted. The seller's record with you shows on the card ("],["i","sold to you 3× · didn't answer 2×"],["t",")."]]},{"li":[["b","Trade helper → Trades"],["t",": "],["b","Sold"],["t",", "],["b","Bought"],["t"," and "],["b","Flips"],["t","."]],"ul":[{"li":[["t","Earned, spent, net profit and a money in / out chart per day."]]},{"li":[["t","Currency swaps (e.g. 300 chaos for 1 div) count by how much they gained or lost at that hour's rate."]]},{"li":[["b","Flips"],["t"," pairs an item you bought with the same item sold later: profit and how long you held it."]]},{"li":[["t","Sales more than 20% under poe.ninja / the exchange are tagged "],["i","under market"],["t","."]]},{"li":[["t","Edit or delete a row, export CSV, and "],["b","+ Add trade"],["t"," for trades done outside the app."]]}]},{"li":[["b","Trade helper → People"],["t",": buyers and sellers in one list, with filters for "],["b","Time wasters"],["t"," (automatic after 2 time wasted / no-show / no answer, or your call), "],["b","Flagged"],["t"," and "],["b","Blocked"],["t"," (popups hidden, or ignored from the app) — with "],["b","Show popups"],["t"," and "],["b","Unignore in game"],["t"," to undo."]]},{"li":[["b","Trade helper → Reports"],["t",": any league or date range, best day, items you sold (count, average, low / high, best buyer), top buyers and sellers, sales under market, and a "],["b","goal"],["t"," (e.g. "],["i","Mageblood, 40 div"],["t",") counting your profit since you set it."]]},{"li":[["b","Today"],["t"," line under the in-game trade cards: earned, spent, net and trades today."]]},{"li":[["b","Setup → Your trade data"],["t",": export a backup file, or import one (it only adds what you don't have)."]]},{"li":[["t","All of it stays on your PC. The only things sent to the game are the buttons you press, one command each."]]}]}],"v":"v2.5.8","date":"2026-11-01"},{"title":"dust explorer","blocks":[{"ul":[{"li":[["b","✨ Dust explorer"],["t"," (Tools → Dust explorer, works without a build): which uniques are worth buying to break down for Thaumaturgic Dust in Kingsmarch."]],"ul":[{"li":[["t","Every unique with its dust, price (the cheapest plain copy on poe.ninja), dust per chaos, gold fee, size and how often it's listed, sorted by dust per chaos."]]},{"li":[["t","Set the item level, quality and extra influences. Hide thin markets or cap the price."]]},{"li":[["t","Uniques that always come influenced (Starforge, Voidwalker…) already count it."]]}]},{"li":[["b","Dust on the price check"],["t",": Ctrl+D (or a pasted unique) shows "],["i","Dust ≈ …"],["t"," next to the quick price, with dust per chaos, from that item's own item level, quality and influences."]]},{"li":[["t","Dust values: the MIT-licensed poe-disenchant-tool dataset (credited in THIRD_PARTY_NOTICES.md)."]]}]}],"v":"v2.5.7","date":"2026-11-01"},{"title":"set the price you got on the trade card","blocks":[{"ul":[{"li":[["b","Sold for"],["t"," on the trade card. Once the buyer is in your hideout, a row above ✓ Completed shows the price, starting at the listed one:"]],"ul":[{"li":[["b","−"],["t"," / "],["b","+"],["t"," change it in steps that suit it (1, 5 or 10 chaos; 0.1, 0.5 or 1 divine);"]]},{"li":[["b","in div"],["t"," / "],["b","in c"],["t"," converts it at the current rate if you were paid in the other currency;"]]},{"li":[["b","Reset"],["t"," goes back to the listed price."]]}]}]},{"p":[["t","✓ Completed records that price in Sales. No typing needed, so the game keeps your keyboard."]]}],"v":"v2.5.6","date":"2026-11-01"},{"title":"poe.ninja links, chat macros, flask and vendor searches, a borderless price check","blocks":[{"ul":[{"li":[["b","poe.ninja ↗"],["t"," for an item's price history: in each card's ⋯ menu (uniques, gems, currency, divination cards), in each gem's ▾ panel, on the Market chart and on the Ctrl+D quick price. It opens in the league you picked."]]},{"li":[["b","Chat macros"],["t"," (⚙ Settings → In game): /kingsmarch, /menagerie, /delve and /exit (log out) to start with. Change them or add your own, up to 12. One click on ▶ or one press of the macro's hotkey sends one command, and the hotkeys only work while the game is focused."]]},{"li":[["b","Search text → Flasks"],["t",": tick the flask mods you want (bleed / freeze / shock / ignite / poison immunity, increased effect, reduced charges per use, instant recovery and more). Every tier of a mod matches."]]},{"li":[["b","Search text → Vendor"],["t",", for levelling: chromatic recipe (R, G and B linked), 3 / 4 / 5 linked sockets, movement speed, + level of socketed gems, added spell damage, life."]]},{"li":[["b","Ctrl+D price check"],["t"," has no title bar now: drag its banner to move it, and resize it from its edges."]]},{"li":[["b","Fix: the app over the game (Shift+Space)"],["t",". Once its title bar was gone, the app could lose track of its own window, so dragging the banner, closing with the hotkey and keeping the overlays up while it's open could stop working."]]}]}],"v":"v2.5.5","date":"2026-11-01"},{"title":"socket colours in the gem compare","blocks":[{"ul":[{"li":[["b","Socket colours"],["t"," (Compare gear → Gems, under the socket picture). Since 3.29 any gem works in any socket, and a gem in a socket of its own colour gets +10% quality. For each of your setups it shows:"]],"ul":[{"li":[["t","how many gems sit in their colour (e.g. "],["i","1 / 4 gems in their colour"],["t",");"]]},{"li":[["t","which colours the link group wants;"]]},{"li":[["t","which colours this base rolls (from its attribute requirements);"]]},{"li":[["t","the crafting bench's "],["i","At Least 2/3/4 Non-White Sockets"],["t"," and its cost (plus Vaal Orbs on a corrupted item);"]]},{"li":[["t","what a Chromatic Orb does on this item;"]]},{"li":[["t","the Omen of Trichromatism when the setup wants all three colours."]]}]}]},{"p":[["t","There are no odds: GGG hasn't published the 3.29 socket colour chances."]]}],"v":"v2.5.4","date":"2026-11-01"},{"title":"cheat sheets for game mechanics","blocks":[{"ul":[{"li":[["b","15 mechanic sheets"],["t"," next to the act sheets (☰ on the sheet, or Tools → Cheat sheets → Mechanics): Betrayal rewards per member and division, Blight oils and anoints, Delve fossils, Incursion temple rooms, Expedition vendors, Sanctum afflictions, Kingsmarch shipping, Ultimatum modifiers, Eldritch altars, the Pantheon (which map boss holds each soul), Vaal Orb outcomes, Bestiary recipes, Harvest crafts, vendor recipes and essences."]],"ul":[{"li":[["t","Built from the Path of Exile Wiki (CC BY-NC-SA) and checked against 3.29's changes; rows the wiki hasn't updated yet are left out rather than shown wrong."]]},{"li":[["t","They update from the app's server between releases, so fixes (and 3.30 changes) don't need a new download."]]}]},{"li":[["b","A small suggestion, not a big window"],["t",": when you enter a mechanic's area, a little pop-up at the top of the game offers its sheet. "],["b","Open"],["t"," shows it, 🔕 stops it for that mechanic, and it goes away by itself after 20 seconds. It's its own piece: drag it anywhere."]]},{"li":[["t","Mechanic tables size themselves to fit, scroll past a max height you can set, and the sheet list is click-only so nothing takes your keyboard from the game."]]}]}],"v":"v2.5.3","date":"2026-11-01"},{"title":"gem setups in Compare gear","blocks":[{"ul":[{"li":[["b","⚖ Compare gear now checks your gems"],["t",", wherever they are. Each PoB link group is matched to your best link group on any item you wear, weapon swap included, so a setup PoB keeps in the body armour still counts when you run it in your helmet (\"your Helmet · 4L (PoB has it in Body Armour) — 4/4 linked\"). Gems in your bag don't count."]],"ul":[{"li":[["t","The Awakened or Vaal version of a build gem counts as having it. The plain gem where the build has the Awakened one, or another transfigured version, counts as close."]]},{"li":[["t","Missing gems, too few links and gems below the build's level or quality are listed."]]}]},{"li":[["b","Every gem shows whether it's linked"],["t",": "],["i","linked · Boots A"],["t",", "],["i","not linked · Boots B"],["t"," (same item, separate link group), "],["i","in Amulet"],["t"," (another item) or "],["i","missing"],["t","."]]},{"li":[["b","Socket picture"],["t",": under each group, your items' link groups drawn as socket chains with the gem in each socket. Separate groups on one item are lettered A, B…, and the group matched to this setup is outlined."]]},{"li":[["b","Unticked gems in PoB"],["t"," are now listed under each setup as options. They're left out of the group's prices, totals and the compare, and if you run one in place of a ticked gem the compare says so."]]}]}],"v":"v2.5.2","date":"2026-11-01"},{"title":"cleaner in-game overlays, new icons","blocks":[{"ul":[{"li":[["b","In-game overlays"],["t",":"]],"ul":[{"li":[["t","Always dark over the game, even with the light theme."]]},{"li":[["t","One look for every panel. Nearly solid by default (95%), with an outline that stands out on bright and dark scenes."]]},{"li":[["t","Text is a size bigger."]]}]},{"li":[["b","Trade cards"],["t",":"]],"ul":[{"li":[["t","Each card says where the trade is at: Waiting, Invited, In your hideout, Trade accepted or Left. The card's coloured edge matches it."]]},{"li":[["t","\"Selling to\" / \"Buying from\"."]]},{"li":[["t","A long name is cut short instead of pushing the ✕ onto its own line."]]},{"li":[["t","The league only shows when it isn't the one you're playing."]]},{"li":[["t","The outcome buttons all look the same, with Completed in green."]]}]},{"li":[["b","The PoB icon"],["t"," over the game is bigger. Its hover buttons now include the cheat sheet and show their hotkeys."]]},{"li":[["b","Cheat sheet"],["t",":"]],"ul":[{"li":[["t","Softer coloured tags."]]},{"li":[["t","Each trial's trap sits under the area name."]]},{"li":[["t","The wiki credit is a tooltip on the title in game (the full line is in Tools → Cheat sheets)."]]}]},{"li":[["b","New icons"],["t",": the sidebar and the overlay buttons use a matching set of gold line icons. Each name stays next to its icon at every window width."]]}]}],"v":"v2.5.1","date":"2026-11-01"},{"title":"cheat sheets, a test mode for the trade helper, light-blue crafted mods","blocks":[{"ul":[{"li":[["b","📜 Cheat sheets"],["t"," (Tools → Cheat sheets; "],["b","Alt+C"],["t"," shows it over the game):"]],"ul":[{"li":[["t","Each act, 1–10: the quests that give a passive point or a respec point, the Trials of Ascendancy and the Labyrinth they open, the bandit rewards, and the resistance penalty after Acts 5 and 10. The data comes from the Path of Exile Wiki (CC BY-NC-SA)."]]},{"li":[["t","Your own sheets: notes and pictures, for one act or for every act."]]},{"li":[["b","Follow my act"],["t"," (asks first) turns the sheet to the act you're in and marks the trial you're standing in. You can also have it pop up when a new act starts."]]},{"li":[["t","Width, size, opacity, lock and reset position; the hotkey can be changed in Settings → In game."]]}]},{"li":[["b","Trade helper → Setup → Test mode"],["t",": see what trades look like over the game without a real buyer. It makes up whispers, the buyer arriving, \"Trade accepted\" and more, or plays a whole trade. Test cards are marked TEST: their buttons send nothing to the game and nothing is saved."]]},{"li":[["b","Crafted and enchanted mods"],["t"," are now bright light blue, so they stand out from the other mods."]]},{"li":[["b","Market"],["t",": the change amount shows next to each percentage."]]}]}],"v":"v2.5.0","date":"2026-11-01"},{"title":"fixes for the app over the game, and a better character compare","blocks":[{"ul":[{"li":[["b","Shift+Space (app over the game)"],["t",": the window no longer flips back to its old size or frame, and clicking in the game puts it away every time, not only after a resize."]]},{"li":[["b","Compare with character"],["t"," now checks every place an item can be:"]],"ul":[{"li":[["t","a jewel counts wherever it is socketed in your tree, not only in the build's socket (your tree jewels are read in the same click);"]]},{"li":[["t","a ring counts in either ring slot;"]]},{"li":[["t","\"Upgrades only\" compares against the item it actually matched."]]}]},{"li":[["t","The Skill tree's "],["b","Compare with my character"],["t"," reuses the data from that click, without asking the site again."]]}]}],"v":"v2.4.2","date":"2026-11-01"},{"title":"tree stages","blocks":[{"ul":[{"li":[["b","🌳 Skill tree: tree stages, like Path of Building."],["t"," If your PoB build has several trees (e.g. \"Level 30\", \"Level 70\", \"Endgame\"), pick one from the menu at the top left of the Skill tree view. The tree active in PoB opens first and is marked. A character comparison carries over when you switch, so you can check your character against the stage you're at."]]},{"li":[["t","Builds whose trees are saved in Path of Building's short form are now read correctly (one tree could hide the next)."]]}]}],"v":"v2.4.1","date":"2026-11-01"},{"title":"skill tree, your own trade sounds, and more","blocks":[{"p":[["b","🌳 Skill tree"],["t"," (Tools → Skill tree): a mini Path of Building inside the app"]]},{"ul":[{"li":[["t","Your build's tree: pan, zoom and search (by node name or stat). Allocated nodes and paths are highlighted."]]},{"li":[["t","Jewel sockets show the jewel your build puts in them; masteries show the effect you picked."]]},{"li":[["t","The ascendancy (and bloodline) sits in its own box."]]},{"li":[["b","Compare with my character"],["t"," (after \"⚖ Compare with character…\" once): shows the points your character still has to take, in the order you can take them (step 1 = can take now), plus any points to refund."]]}]},{"h":[["t","Trade helper"]]},{"ul":[{"li":[["b","Your own sounds"],["t",": Setup → Sound → \"Your own sound…\". Use an mp3, wav, ogg or m4a, one for a new trade and, optionally, one for when the buyer arrives. Plays at your volume."]]},{"li":[["b","Show in stash on quad tabs"],["t",": the whisper doesn't say whether it's a quad tab, so both cells are outlined: amber for a normal tab, blue for a quad tab."]]},{"li":[["b","One player, several characters"],["t",": Buyers → \"Same person as…\" merges them, so their history adds up."]]}]},{"h":[["t","Tools"]]},{"ul":[{"li":[["b","Watcher's Eye"],["t",": "],["b","Price each triple"],["t"," (jewels with three of your mods), plus "],["b","Include legacy mods"],["t"," for old jewels."]]},{"li":[["b","Div cards"],["t",": prices of 1 divine or more show in divines."]]},{"li":[["b","Search text"],["t",": every map mod can now be searched."]]}]}],"v":"v2.4.0","date":"2026-11-01"},{"title":"trade helper, in-game overlays, Watcher's Eye & co., search text, div cards","blocks":[{"p":[["b","In game"],["t"," (play in Windowed or Windowed Fullscreen; true fullscreen hides overlays)"]]},{"ul":[{"li":[["b","PoB icon over the game"],["t",": a green dot means it's running, plus a count of open trades. Click it for your trade cards. Drag it anywhere; it sticks to the game window."]]},{"li":[["b","Hotkeys"],["t"," (Settings → In game): "],["b","Ctrl+D"],["t"," prices an item, "],["b","Shift+Space"],["t"," brings the whole app over the game, "],["b","Alt+T"],["t"," shows or hides the trade cards."]]},{"li":[["t","The app over the game resizes from its edges or with − / +. Drag its banner to move it. Esc, the hotkey or a click in the game puts it away."]]},{"li":[["b","Tray icon"],["t",": closing the window keeps the app running. Right-click the tray icon to quit."]]}]},{"p":[["b","🤝 Trade helper"],["t"," (Tools → Trade helper; switch it on in Setup)"]]},{"ul":[{"li":[["t","A card for every trade whisper. "],["b","Invite · Busy · Sold · Still interested?"],["t",", then "],["b","Trade · Kick · Thanks"],["t"," once the buyer is in your hideout. Record the outcome with ✓ Completed, ✗ Not completed, ⌛ Time wasted or no-show."]]},{"li":[["b","Each button sends exactly one chat command"],["t"," when you press it. Nothing is ever sent on its own."]]},{"li":[["b","▣ Show in stash"],["t"," outlines the item's cell."]]},{"li":[["b","Your own buttons"],["t"," (a label and a message) and a stacked or side-by-side card layout."]]},{"li":[["b","Sales"],["t",": chaos and divine prices, totals, a chart, best sellers, edit and CSV export. "],["b","Buyers"],["t",": reputation, notes, flag, hide, and ignore in game once."]]},{"li":[["t","Sounds with a volume slider, overlay opacity and size, and zone notes."]]},{"li":[["t","Everything stays on your PC; the app only reads the game's chat log."]]}]},{"h":[["t","New tools"]]},{"ul":[{"li":[["b","👁 Watcher's Eye & co."],["t",":"]],"ul":[{"li":[["t","Watcher's Eye with your build's auras pre-picked, current mods only and pair pricing."]]},{"li":[["t","Forbidden Flame & Flesh pairs for your ascendancy."]]},{"li":[["t","Thread of Hope ring sizes."]]}]},{"li":[["b","🔤 Search text"],["t"," (like poe.re): map mods to avoid or want, item quantity, or your own words, with presets. "],["b","Paste into game"],["t"," fills the stash search box in one press."]]},{"li":[["b","🃏 Div cards"],["t",": which areas drop the valuable cards, and where each card drops."]]},{"li":[["b","Learned filters"],["t",": pasted and Ctrl+D items remember the mods you always switch on or off."]]}]},{"h":[["t","Fixes"]]},{"ul":[{"li":[["t","The app no longer fails to start when unzipped from a browser download (the \"Python.Runtime\" error)."]]},{"li":[["t","Every window close and exit is written to "],["c","data\\debug.log"],["t"," to help track down problems."]]}]}],"v":"v2.3.0","date":"2026-11-01"},{"title":"trade helper","blocks":[{"p":[["b","🤝 Trade helper"],["t"," (Tools → Trade helper, or ⚙ Settings → In game). A small window that stays on top of the game, with a card for every trade whisper."]]},{"ul":[{"li":[["b","Selling:"],["t"," Invite · Busy · Sold · Still interested?. When the buyer arrives the card shows "],["b","In your hideout"],["t"," and switches to Trade · Kick · Thanks. Then record the outcome: "],["b","✓ Completed"],["t"," (confirm the price), "],["b","✗ Not completed"],["t",", "],["b","⌛ Time wasted"],["t"," or "],["b","Other"],["t",". \"Trade accepted\" in the game highlights Completed for you. Invited buyers who don't show up can be marked "],["b","no-show"]]},{"li":[["b","▣ Show in stash"],["t"," outlines the item's cell over your open stash tab (quad tabs too)"]]},{"li":[["b","Buying:"],["t"," cards for whispers you send, with Visit hideout · Trade · Re-whisper"]]},{"li":[["b","Sales:"],["t"," every sale in chaos and divines, with totals per league and per day, best sellers, average, a chart, filters and CSV export"]]},{"li":[["b","Buyers:"],["t"," completed trades, total spent, time wasted and no-shows (shown as a badge on their next whisper), private notes, flag, hide popups, and "],["b","Ignore in game"],["t"," (sends /ignore once)"]]}]},{"p":[["b","How it plays by GGG's rules:"],["t"," each button sends exactly one chat command when you press it. Nothing is sent on a timer or because of something in the log. Invite and Trade are separate buttons. The app reads Client.txt only after you switch the helper on, and your sales and buyer notes never leave your PC."]]}],"v":"v2.2.0","date":"2026-11-06"},{"title":"smarter price checks","blocks":[{"p":[["b","Is it an upgrade?"],["t"," Ctrl+D or paste an item and the card compares it with your build's item for that slot (both rings for a ring) and with what your imported character wears: "],["b","Upgrade / Sidegrade / Downgrade"],["t"," with a % and the stat differences. It's a stat comparison, not a DPS calculation."]]},{"h":[["t","Quick price, no trade search needed"]]},{"ul":[{"li":[["t","Currency, fragments, scarabs, essences and cards are priced instantly from GGG's hourly exchange feed, with your stack's value"]]},{"li":[["t","Uniques and gems come from poe.ninja through the app's own server (refreshed about every 30 minutes)"]]},{"li":[["b","Live offers"],["t"," (exchange items): asks the trade site's bulk exchange who sells it right now. It sends one request each time you press it"]]}]},{"h":[["t","Better filters for one item"]]},{"ul":[{"li":[["t","Ctrl+C copies carry mod tiers now ("],["b","T1, T2…"],["t","). Mods worse than tier 2 start unticked, and minimums are 90% of each roll"]]},{"li":[["b","Preset"],["t",": "],["b","Similar"],["t"," (those defaults), "],["b","Exact"],["t"," (every mod at full roll, exact base) or "],["b","Base"],["t"," (no mods: the base, item level and influence alone)"]]},{"li":[["t","New search settings: "],["b","Listed within"],["t"," (skip old, often abandoned listings) and "],["b","Priced in"],["t"," (chaos / divine / either)"]]},{"li":[["t","⋯ → "],["b","Open on PoE Wiki / PoEDB"]]}]},{"h":[["t","Listings"]]},{"ul":[{"li":[["t","Seller status dot (online / away / offline) and how long ago each item was listed"]]},{"li":[["t","The same seller listing several copies at one price shows once, with "],["b","×N"]]},{"li":[["t","Your own listings get a "],["b","You"],["t"," badge (set your account name in Settings)"]]},{"li":[["t","Re-checking the same search within 5 minutes uses the earlier result and says how old it is. "],["b","↻ Refresh"],["t"," searches again"]]}]},{"p":[["b","Data"],["t",": trade stats and unique roll ranges refreshed."]]}],"v":"v2.1.0","date":"2026-11-01"},{"title":"new themes, menu fix at larger text, clearer messages","blocks":[{"p":[["b","Three new themes"],["t"," (⚙ Settings → Appearance → Theme)"]]},{"ul":[{"li":[["b","Dim"],["t",": dark but not too dark, warm charcoal instead of near-black"]]},{"li":[["b","Slate"],["t",": a cool blue-grey dark"]]},{"li":[["b","Parchment"],["t",": a warm, low-glare light, easier on the eyes than white"]]}]},{"p":[["t","All five themes work with every accent and High contrast, and every combination is checked for readable contrast."]]},{"h":[["t","Fixes"]]},{"ul":[{"li":[["t","With Text size above Normal, the "],["b","⋯"],["t"," menu and the Search settings popover opened off to the side (sometimes past the window edge). They now open right under their button at every text size."]]},{"li":[["b","\"Query is too complex\""],["t"," (weighted or flexible-resistance searches without being logged in) is now explained in plain words, with buttons to open the search on the trade site, search \"all but one\" instead, or add a POESESSID."]]}]},{"h":[["t","POESESSID"]]},{"ul":[{"li":[["t","Still optional and still yours to use. The first time you save one, a short notice explains what it is (your logged-in session: never share it), that GGG doesn't officially support third-party tools using it, and how to stop. Confirm once and it never asks again."]]}]}],"v":"v2.0.6","date":"2026-11-01"},{"title":"weighted upgrade search, value per chaos, playing by GGG's rules","blocks":[{"h":[["t","Weighted upgrade search"]]},{"ul":[{"li":[["t","New "],["b","Match → weighted total (any mix)"],["t"," under More filters: every ticked mod is worth 100 points at your item's roll, and a listing needs the "],["b","Target"],["t"," share of the total (90% by default; 110% = an upgrade). More of one stat can make up for less of another, like Path of Building's own trade search. In-app checks of these heavier searches may need a saved POESESSID; the trade-site link works while you're logged in there."]]}]},{"h":[["t","Value per chaos"]]},{"ul":[{"li":[["t","Each listing shows "],["b","\"% of your item\""],["t"," (how it compares on the stats you searched) and the "],["b","price per %"],["t",". "],["b","Best value first"],["t"," re-sorts the page so the most stats per chaos come first."]]}]},{"h":[["t","Playing by GGG's rules"]]},{"ul":[{"li":[["t","Saved-build tracking no longer searches on its own. When a build's prices are a day old you get a reminder with "],["b","Re-price now"],["t","; nothing is searched without your click."]]},{"li":[["b","Check all prices"],["t"," (and Price changed slots, gem pricing, Value my gear) go one search at a time with a short gap, and the same button now "],["b","stops"],["t"," them. A rate-limit cooldown ends the batch."]]},{"li":[["t","The app identifies itself to GGG's servers with its name, version and a contact link."]]},{"li":[["t","The Market's feed checks follow GGG's documented polling rules."]]},{"li":[["t","Clearer notices: \"This product isn't affiliated with or endorsed by Grinding Gear Games in any way.\" (footer, README, new Settings → About), and a note on what the optional POESESSID does. Your POESESSID is now only ever sent to the trade site itself."]]}]},{"h":[["t","Coming: official login and Stash value"]]},{"ul":[{"li":[["t","GGG's official Path of Exile login and a "],["b","Stash value"],["t"," page (every tab valued at the exchange prices, charted over time) are built in but switched off: GGG isn't accepting new apps for its official login yet. They turn on in an update once it approves this one."]]}]}],"v":"v2.0.5","date":"2026-11-01"},{"title":"build diff, daily build tracking, wide screens, price gaps","blocks":[{"h":[["t","Loading a newer version of a build"]]},{"ul":[{"li":[["t","Paste an updated PoB of the same build and a "],["b","Changed since the version you loaded…"],["t"," list appears above the gear: what changed in each slot (the item, or the mod lines added and removed), what it cost when you last priced the old version, and, after "],["b","Price changed slots"],["t",", what it costs now and the difference."]]},{"li":[["t","Changed slots are marked in the slot list, and unchanged slots keep their cost history."]]}]},{"h":[["t","Daily price tracking for saved builds"]]},{"ul":[{"li":[["t","Press "],["b","📈"],["t"," on a saved build: re-price it once a day, with an optional alert when it costs at or under a price. It re-runs your last search for each slot you priced, slowly and never during a rate-limit cooldown. The card shows the latest total and the change."]]}]},{"h":[["t","Wide screens"]]},{"ul":[{"li":[["t","On very wide windows (ultrawide), item pages use the extra room and a priced item shows its listings beside its mods instead of below them."]]}]},{"h":[["t","Market: chaos ↔ divine price gaps"]]},{"ul":[{"li":[["t","Items that traded against both chaos and divines last hour at noticeably different prices, with which way round was cheaper and how much traded (2,000c an hour or more by default). These are last hour's averages: check the live exchange before trading."]]}]},{"h":[["t","Fewer wasted trade calls"]]},{"ul":[{"li":[["t","A unique or gem whose art lookup fails for good (unknown name, nothing ever listed) is no longer looked up again on every launch; it's retried after a week."]]}]},{"h":[["t","Under the hood"]]},{"ul":[{"li":[["t","The app's main script is split into 16 smaller files, and a new end-to-end test suite (11 scenarios in headless Chrome) runs the real interface before every release."]]}]}],"v":"v2.0.4","date":"2026-10-31"},{"title":"list-price suggestion, build cost history, diagnostics","blocks":[{"h":[["t","Selling: \"List at ~X\""]]},{"ul":[{"li":[["t","Items you price with "],["b","Ctrl+D"],["t"," in game, or paste into the main window, now show a suggested list price above the listings. It matches the cheapest "],["i","real"],["t"," competitor: listings under 60% of the typical price are bait or price fixers and are ignored."]]},{"li":[["b","Open full search ↗"],["t"," opens the same search on the trade site."]]},{"li":[["t","No extra trade-site calls: it reads the listings already fetched."]]}]},{"h":[["t","Build cost over time"]]},{"ul":[{"li":[["t","Every pricing session is remembered per build. The Upgrade planner shows the change since your last check with a chart, and the sidebar build card shows the cost and the change (▼ green when it got cheaper, ▲ red when it got dearer)."]]},{"li":[["t","Sessions are compared on the same slots, so pricing more slots never looks like a price change."]]},{"li":[["t","Reloading a saved build shows what it cost when you last priced it."]]}]},{"h":[["t","Reporting a problem"]]},{"ul":[{"li":[["b","⚙ Settings → Copy diagnostics"],["t"," copies the app version, Windows version, data dates, recent errors and log lines for a bug report. Your POESESSID, other tokens and your Windows user name are removed."]]},{"li":[["c","data/debug.log"],["t"," now records failed trade-site requests and is capped at 256 KB."]]}]}],"v":"v2.0.3","date":"2026-10-31"},{"title":"new-league banner, price alerts","blocks":[{"h":[["t","New league? One click"]]},{"ul":[{"li":[["t","The app checks GGG's league list when it starts and every 6 hours. When a new challenge league goes live, a banner offers "],["b","Switch to <league>"],["t",": it refreshes the trade data, moves every search and price to the new league, and reloads. "],["b","Not now"],["t"," hides it for that league."]]}]},{"h":[["t","Price alerts (Market)"]]},{"ul":[{"li":[["t","Press "],["b","🔔 Alert"],["t"," above any item's chart: "],["i","rises above"],["t"," or "],["i","falls below"],["t"," a price (chaos or divine), or "],["i","moves more than X% in 24 hours"],["t","."]]},{"li":[["t","Checked each hour while the app is open. Each alert fires once when the price crosses the level and again only after it has crossed back. You get an in-app message with a "],["b","View"],["t"," button, plus a Windows notification when the app is in the background."]]},{"li":[["t","Items with an alert join your watchlist and show 🔔 there."]]}]},{"h":[["t","Fixes"]]},{"ul":[{"li":[["t","The converter reads \"Worth 371 chaos\" instead of starting with a stray \"=\", and no longer repeats the currency you typed in or shows tiny divine fractions."]]},{"li":[["b","Install & restart"],["t"," into this version should no longer show the \".NET unhandled exception\" box (the fix shipped in 2.0.1; this is the first update that runs it)."]]}]}],"v":"v2.0.2","date":"2026-10-31"},{"title":"new Market page, Gems page, fixes","blocks":[{"h":[["t","Market"]]},{"ul":[{"li":[["t","Covers every item on GGG's currency exchange in your league (~480: currency, fossils, essences, oils, scarabs, catalysts, cards and more), not just 14 currencies."]]},{"li":[["b","Biggest movers"],["t"," over 24 hours or 7 days. Thin markets are left out because single trades swing their price."]]},{"li":[["t","Click any item to chart it, with price and date axes, hover values and traded volume. Pick "],["b","1 day / 7 days / 30 days"],["t",". Change, low, high and typical volume are shown under the chart."]]},{"li":[["b","Watchlist"],["t"," (☆ any item) and a chaos ↔ divine "],["b","converter"],["t"," for any item."]]},{"li":[["t","A table you can search, filter by category, and sort, with 24h and 7-day change, range, volume and trend lines."]]},{"li":[["t","History is now 6-hourly. The first visit downloads about 13 MB from GGG's feed; after that it's cached on your PC."]]}]},{"h":[["t","Gems"]]},{"ul":[{"li":[["t","Laid out like the gear pages: link groups on the left (your main skill ★ opens first, with group totals once priced) and the selected group's gems on the right. "],["b","Price this group"],["t"," / "],["b","Price all gems"],["t",", and "],["b","▾"],["t"," on any gem for full listings and live search."]]}]},{"h":[["t","Fixes"]]},{"ul":[{"li":[["b","Install & restart"],["t"," no longer shows a \".NET unhandled exception\" box. It closed the hidden price-check window twice. The update into 2.0.1 still runs 2.0.0's shutdown code, so you may see the box one last time."]]},{"li":[["b","⚙ Settings"],["t"," (and "],["b","Check for updates"],["t"," inside it) disappeared below the window when Text size was above Normal. It's now pinned to the bottom of the sidebar."]]},{"li":[["t","Unique items in the slot list now show their real art instead of the base item's."]]},{"li":[["t","Anoints and other enchants are labelled "],["i","enchant"],["t",", not "],["i","crafted"],["t","."]]},{"li":[["t","On wide screens, pages now start beside the sidebar instead of floating in the middle."]]}]}],"v":"v2.0.1","date":"2026-10-31"},{"title":"redesigned interface","blocks":[{"p":[["t","The whole app has a new layout and look. Searches, prices and everything else work the same way; your saved builds, basket, history and settings carry over."]]},{"h":[["t","New layout"]]},{"ul":[{"li":[["t","A "],["b","sidebar"],["t"," holds your build (gear set, save, switch build, compare with character) and the pages: Gear, Jewels & clusters, Flasks, Gems, Upgrade planner, Timeless jewels, Jewel finder, Market."]]},{"li":[["t","Gear, jewels and flasks show a "],["b","slot list"],["t"," beside one item at a time, with each slot's price or status (Bought, None listed, Equipped, Missing). No more scrolling through every card. Arrow keys move through the list."]]},{"li":[["t","The "],["b","top bar"],["t"," shows the search settings in use; change them under "],["b","Search settings ▾"],["t","."]]},{"li":[["t","A new "],["b","start screen"],["t",": paste box, saved builds as one-click cards, and how it works."]]}]},{"h":[["t","Item cards"]]},{"ul":[{"li":[["b","Check price"],["t",", "],["b","Go live"],["t"," and "],["b","Search on trade"],["t"," sit next to the item name; Copy URL, Craft vs buy, Find seeds and Mark bought are under "],["b","⋯"],["t","."]]},{"li":[["t","The less-used filters (Search by, Match, ilvl, sockets, links, min roll, max price) fold into "],["b","More filters"],["t",", which shows how many you've changed."]]},{"li":[["t","Listings show the price bigger and one main button: "],["b","Go to hideout"],["t"," for instant buyout, "],["b","Whisper"],["t"," for in-person. Pin, Copy whisper and /hideout are under "],["b","⋯"],["t","."]]}]},{"h":[["t","Tool pages"]]},{"ul":[{"li":[["b","Upgrade planner"],["t",": build cost and the basket as sortable tables (click an item to jump to its slot), plus the budget solver."]]},{"li":[["b","Timeless jewels"],["t"," and "],["b","Jewel finder"],["t"," read as numbered steps. The jewel finder has one "],["b","Off / Want / Must"],["t"," switch per mod instead of two checkboxes."]]},{"li":[["b","Market"],["t",": a large 7-day Divine Orb chart above the currency table."]]},{"li":[["b","Settings"],["t"," opens as a panel on the right, grouped into Appearance, Accessibility, Alerts, In game, Account (your POESESSID now lives here) and Data."]]}]},{"h":[["t","Look and accessibility"]]},{"ul":[{"li":[["b","Dark"],["t"," and "],["b","Light"],["t"," themes (or match Windows) with five accent colours, replacing the six old schemes; your old choice is carried over. Every text colour is checked for readable contrast in every combination."]]},{"li":[["t","No text smaller than 12px, visible keyboard focus everywhere, labels on every control, and states shown with words as well as colour."]]},{"li":[["t","Deleting a saved build, clearing the basket or removing an item now asks first."]]},{"li":[["t","The window opens at 1280×900; narrower windows get an icon sidebar, and very narrow ones stack everything."]]}]}],"v":"v2.0.0","date":"2026-10-31"}];
